1	package com.example.starter.translation.service;
2	
3	import com.example.starter.translation.api.ApiDtos;
4	import com.example.starter.translation.api.ApiException;
5	import com.example.starter.translation.domain.Rows.ApprovalRow;
6	import com.example.starter.translation.domain.Rows.DocumentRow;
7	import com.example.starter.translation.domain.Rows.SegmentRow;
8	import com.example.starter.translation.domain.Rows.TranslationRow;
9	import com.example.starter.translation.repo.TranslationRepository;
10	import com.fasterxml.jackson.databind.ObjectMapper;
11	import org.springframework.stereotype.Service;
12	import org.springframework.transaction.annotation.Transactional;
13	
14	import java.util.ArrayList;
15	import java.util.LinkedHashMap;
16	import java.util.List;
17	import java.util.Locale;
18	import java.util.Map;
19	import java.util.function.Function;
20	import java.util.stream.Collectors;
21	
22	/**
23	 * 多语种段落修订与发布快照的核心业务服务。
24	 * 所有写操作先对文档行加 FOR UPDATE 行锁，保证同一文档的修改、审核与发布串行，
25	 * 并发下对应一个一致的文档状态；方法均加入调用方事务，与幂等记录原子提交。
26	 */
27	@Service
28	public class TranslationService {
29	
30	    private final TranslationRepository repository;
31	    private final ObjectMapper objectMapper;
32	
33	    public TranslationService(TranslationRepository repository, ObjectMapper objectMapper) {
34	        this.repository = repository;
35	        this.objectMapper = objectMapper;
36	    }
37	
38	    /** 建文档：1~5 种目标语言，可携带初始段落，初始草稿版本 1、发布版本 0。 */
39	    @Transactional
40	    public ApiDtos.DocumentResponse createDocument(ApiDtos.CreateDocumentRequest request) {
41	        List<String> languages = normalizeLanguages(request.targetLanguages());
42	        List<ApiDtos.SegmentInput> segments = request.segments();
43	        long distinct = segments.stream().map(ApiDtos.SegmentInput::segmentId).distinct().count();
44	        if (distinct != segments.size()) {
45	            throw ApiException.unprocessable("初始段落 segmentId 重复");
46	        }
47	        long documentId = repository.insertDocument(languages);
48	        for (ApiDtos.SegmentInput segment : segments) {
49	            repository.insertSegment(documentId, segment.segmentId(), segment.sourceText());
50	        }
51	        return new ApiDtos.DocumentResponse(documentId, 1, 0, languages);
52	    }
53	
54	    /** 增加段落：segmentId 文档内唯一，草稿版本加一。 */
55	    @Transactional
56	    public ApiDtos.SegmentResponse addSegment(long documentId, ApiDtos.AddSegmentRequest request) {
57	        DocumentRow document = lockDocument(documentId);
58	        if (repository.findSegment(documentId, request.segmentId()).isPresent()) {
59	            throw ApiException.conflict("段落已存在: " + request.segmentId());
60	        }
61	        repository.insertSegment(documentId, request.segmentId(), request.sourceText());
62	        int draftVersion = bumpDraftVersion(document);
63	        return new ApiDtos.SegmentResponse(documentId, request.segmentId(), 1, draftVersion);
64	    }
65	
66	    /** 源文修订：源文版本加一、草稿版本加一；相关译文因源文版本落后而待更新。 */
67	    @Transactional
68	    public ApiDtos.SegmentResponse reviseSource(long documentId, String segmentId,
69	                                              ApiDtos.ReviseSourceRequest request) {
70	        DocumentRow document = lockDocument(documentId);
71	        SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
72	        int sourceVersion = segment.sourceVersion() + 1;
73	        repository.updateSegmentSource(documentId, segmentId, request.sourceText(), sourceVersion);
74	        int draftVersion = bumpDraftVersion(document);
75	        return new ApiDtos.SegmentResponse(documentId, segmentId, sourceVersion, draftVersion);
76	    }
77	
78	    /** 译文提交：所依据源文版本必须等于当前源文版本；译文版本递增，草稿版本加一。 */
79	    @Transactional
80	    public ApiDtos.TranslationResponse submitTranslation(long documentId, String segmentId, String language,
81	                                                         String actorId, ApiDtos.SubmitTranslationRequest request) {
82	        DocumentRow document = lockDocument(documentId);
83	        String normalizedLanguage = normalizeLanguage(language);
84	        if (!document.targetLanguages().contains(normalizedLanguage)) {
85	            throw ApiException.unprocessable("语言不在文档目标语言中: " + normalizedLanguage);
86	        }
87	        SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
88	        if (request.sourceVersion() != segment.sourceVersion()) {
89	            throw ApiException.unprocessable("译文所依据的源文版本 " + request.sourceVersion()
90	                    + " 与当前源文版本 " + segment.sourceVersion() + " 不匹配");
91	        }
92	        int translationVersion = repository.findTranslation(documentId, segmentId, normalizedLanguage)
93	                .map(TranslationRow::translationVersion).orElse(0) + 1;
94	        repository.upsertTranslation(documentId, new TranslationRow(segmentId, normalizedLanguage,
95	                request.content(), actorId, segment.sourceVersion(), translationVersion));
96	        int draftVersion = bumpDraftVersion(document);
97	        return new ApiDtos.TranslationResponse(documentId, segmentId, normalizedLanguage,
98	                translationVersion, segment.sourceVersion(), draftVersion);
99	    }
100	
101	    /** 译文批准：审核人不得是作者，且必须同时匹配当前源文与译文版本。 */
102	    @Transactional
103	    public ApiDtos.ApprovalResponse approveTranslation(long documentId, String segmentId, String language,
104	                                                       String actorId, ApiDtos.ApproveTranslationRequest request) {
105	        lockDocument(documentId);
106	        String normalizedLanguage = normalizeLanguage(language);
107	        SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
108	        TranslationRow translation = repository.findTranslation(documentId, segmentId, normalizedLanguage)
109	                .orElseThrow(() -> ApiException.notFound(
110	                        "译文不存在: " + segmentId + "/" + normalizedLanguage));
111	        if (translation.author().equals(actorId)) {
112	            throw ApiException.unprocessable("审核人不得是该译文作者");
113	        }
114	        if (translation.translationVersion() != request.translationVersion()) {
115	            throw ApiException.unprocessable("批准所针对的译文版本 " + request.translationVersion()
116	                    + " 与当前译文版本 " + translation.translationVersion() + " 不匹配");
117	        }
118	        if (translation.sourceVersion() != segment.sourceVersion()) {
119	            throw ApiException.unprocessable("译文基于源文版本 " + translation.sourceVersion()
120	                    + "，当前源文版本 " + segment.sourceVersion() + "，译文待更新，不能批准");
121	        }
122	        repository.upsertApproval(documentId, new ApprovalRow(segmentId, normalizedLanguage, actorId,
123	                segment.sourceVersion(), translation.translationVersion()));
124	        return new ApiDtos.ApprovalResponse(documentId, segmentId, normalizedLanguage, actorId,
125	                translation.translationVersion(), segment.sourceVersion());
126	    }
127	
128	    /**
129	     * 发布：校验期望版本（不符 409），再校验全部段落在全部目标语言均有有效批准（缺译或审核失效 422），
130	     * 全部通过后原子生成完整只读快照并递增发布版本；任何失败回滚，不产生部分快照。
131	     */
132	    @Transactional
133	    public ApiDtos.PublishResponse publish(long documentId, ApiDtos.PublishRequest request) {
134	        DocumentRow document = lockDocument(documentId);
135	        if (document.draftVersion() != request.expectedDraftVersion()
136	                || document.publishedVersion() != request.expectedPublishedVersion()) {
137	            throw ApiException.conflict("版本冲突：当前草稿版本 " + document.draftVersion()
138	                    + "、发布版本 " + document.publishedVersion() + "，与期望的 "
139	                    + request.expectedDraftVersion() + "/" + request.expectedPublishedVersion() + " 不一致");
140	        }
141	        List<SegmentRow> segments = repository.listSegments(documentId);
142	        Map<String, TranslationRow> translations = repository.listTranslations(documentId).stream()
143	                .collect(Collectors.toMap(t -> key(t.segmentId(), t.language()), Function.identity()));
144	        Map<String, ApprovalRow> approvals = repository.listApprovals(documentId).stream()
