59	    /** 源文修订：源文版本加一、相关译文待更新、草稿版本加一；不影响已发布快照。 */
60	    @PutMapping("/{documentId}/segments/{segmentId}/source")
61	    public ResponseEntity<String> reviseSource(@PathVariable long documentId, @PathVariable String segmentId,
62	                                               @Valid @RequestBody ApiDtos.ReviseSourceRequest request) {
63	        String operation = "PUT /api/documents/" + documentId + "/segments/" + segmentId + "/source";
64	        return writeExecutor.execute(request.requestId(), hash(operation, request),
65	                () -> WriteResult.of(200, translationService.reviseSource(documentId, segmentId, request)))
66	                .toResponseEntity();
67	    }
68	
69	    /** 译文提交：作者取 X-Actor-Id，所依据源文版本必须匹配当前源文版本。 */
70	    @PutMapping("/{documentId}/segments/{segmentId}/translations/{language}")
71	    public ResponseEntity<String> submitTranslation(@PathVariable long documentId, @PathVariable String segmentId,
72	                                                    @PathVariable String language,
73	                                                    @RequestHeader("X-Actor-Id") String actorId,
74	                                                    @Valid @RequestBody ApiDtos.SubmitTranslationRequest request) {
75	        String operation = "PUT /api/documents/" + documentId + "/segments/" + segmentId
76	                + "/translations/" + language;
77	        return writeExecutor.execute(request.requestId(), hash(operation, actorId, request),
78	                () -> WriteResult.of(200, translationService.submitTranslation(
79	                        documentId, segmentId, language, actorId, request))).toResponseEntity();
80	    }
