1	package com.example.starter.translation.repo;
2	
3	import com.example.starter.translation.domain.Rows.ApprovalRow;
4	import com.example.starter.translation.domain.Rows.DocumentRow;
5	import com.example.starter.translation.domain.Rows.RequestLogRow;
6	import com.example.starter.translation.domain.Rows.SegmentRow;
7	import com.example.starter.translation.domain.Rows.TranslationRow;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.jdbc.core.RowMapper;
10	import org.springframework.jdbc.support.GeneratedKeyHolder;
11	import org.springframework.jdbc.support.KeyHolder;
12	import org.springframework.stereotype.Repository;
13	
14	import java.sql.PreparedStatement;
15	import java.util.Arrays;
16	import java.util.List;
17	import java.util.Optional;
18	
19	/**
20	 * 多语种段落发布的数据访问层，基于 JdbcTemplate 与参数化 SQL。
21	 * 目标语言在 document 表中以逗号分隔存储，行记录中还原为列表。
22	 */
23	@Repository
24	public class TranslationRepository {
25	
26	    private static final RowMapper<DocumentRow> DOCUMENT_MAPPER = (rs, n) -> new DocumentRow(
27	            rs.getLong("document_id"),
28	            Arrays.stream(rs.getString("target_languages").split(",")).toList(),
29	            rs.getInt("draft_version"),
30	            rs.getInt("published_version"));
31	
32	    private static final RowMapper<SegmentRow> SEGMENT_MAPPER = (rs, n) -> new SegmentRow(
33	            rs.getString("segment_id"), rs.getString("source_text"), rs.getInt("source_version"));
34	
35	    private static final RowMapper<TranslationRow> TRANSLATION_MAPPER = (rs, n) -> new TranslationRow(
36	            rs.getString("segment_id"), rs.getString("language"), rs.getString("content"),
37	            rs.getString("author"), rs.getInt("source_version"), rs.getInt("translation_version"));
38	
39	    private static final RowMapper<ApprovalRow> APPROVAL_MAPPER = (rs, n) -> new ApprovalRow(
40	            rs.getString("segment_id"), rs.getString("language"), rs.getString("reviewer"),
41	            rs.getInt("source_version"), rs.getInt("translation_version"));
42	
43	    private final JdbcTemplate jdbc;
44	
45	    public TranslationRepository(JdbcTemplate jdbc) {
46	        this.jdbc = jdbc;
47	    }
48	
49	    /** 插入文档并返回自增 ID，初始草稿版本 1、发布版本 0。 */
50	    public long insertDocument(List<String> targetLanguages) {
51	        KeyHolder keyHolder = new GeneratedKeyHolder();
52	        jdbc.update(con -> {
53	            PreparedStatement ps = con.prepareStatement(
54	                    "INSERT INTO document (target_languages, draft_version, published_version) VALUES (?, 1, 0)",
55	                    new String[]{"document_id"});
56	            ps.setString(1, String.join(",", targetLanguages));
57	            return ps;
58	        }, keyHolder);
59	        Number key = keyHolder.getKey();
60	        if (key == null) {
61	            throw new IllegalStateException("文档创建后未返回自增主键");
62	        }
63	        return key.longValue();
64	    }
65	
66	    /** 按 ID 查询文档并加行级写锁（FOR UPDATE），用于串行化同一文档的写操作。 */
67	    public Optional<DocumentRow> findDocumentForUpdate(long documentId) {
68	        List<DocumentRow> rows = jdbc.query(
69	                "SELECT document_id, target_languages, draft_version, published_version "
70	                        + "FROM document WHERE document_id = ? FOR UPDATE",
71	                DOCUMENT_MAPPER, documentId);
72	        return rows.stream().findFirst();
73	    }
74	
75	    /** 只读查询文档（不加锁），用于快照查询。 */
76	    public Optional<DocumentRow> findDocument(long documentId) {
77	        List<DocumentRow> rows = jdbc.query(
78	                "SELECT document_id, target_languages, draft_version, published_version "
79	                        + "FROM document WHERE document_id = ?",
80	                DOCUMENT_MAPPER, documentId);
81	        return rows.stream().findFirst();
82	    }
83	
84	    public void updateDraftVersion(long documentId, int draftVersion) {
85	        jdbc.update("UPDATE document SET draft_version = ? WHERE document_id = ?", draftVersion, documentId);
86	    }
87	
88	    public void updatePublishedVersion(long documentId, int publishedVersion) {
89	        jdbc.update("UPDATE document SET published_version = ? WHERE document_id = ?", publishedVersion, documentId);
90	    }
91	
92	    public void insertSegment(long documentId, String segmentId, String sourceText) {
93	        jdbc.update("INSERT INTO segment (document_id, segment_id, source_text, source_version) VALUES (?, ?, ?, 1)",
94	                documentId, segmentId, sourceText);
95	    }
96	
97	    public Optional<SegmentRow> findSegment(long documentId, String segmentId) {
98	        List<SegmentRow> rows = jdbc.query(
99	                "SELECT segment_id, source_text, source_version FROM segment "
100	                        + "WHERE document_id = ? AND segment_id = ?",
101	                SEGMENT_MAPPER, documentId, segmentId);
102	        return rows.stream().findFirst();
103	    }
104	
105	    public List<SegmentRow> listSegments(long documentId) {
106	        return jdbc.query(
107	                "SELECT segment_id, source_text, source_version FROM segment "
108	                        + "WHERE document_id = ? ORDER BY segment_id",
109	                SEGMENT_MAPPER, documentId);
110	    }
111	
112	    public void updateSegmentSource(long documentId, String segmentId, String sourceText, int sourceVersion) {
113	        jdbc.update("UPDATE segment SET source_text = ?, source_version = ? "
114	                        + "WHERE document_id = ? AND segment_id = ?",
115	                sourceText, sourceVersion, documentId, segmentId);
116	    }
117	
118	    public Optional<TranslationRow> findTranslation(long documentId, String segmentId, String language) {
119	        List<TranslationRow> rows = jdbc.query(
120	                "SELECT segment_id, language, content, author, source_version, translation_version "
121	                        + "FROM translation WHERE document_id = ? AND segment_id = ? AND language = ?",
122	                TRANSLATION_MAPPER, documentId, segmentId, language);
123	        return rows.stream().findFirst();
124	    }
125	
126	    public List<TranslationRow> listTranslations(long documentId) {
127	        return jdbc.query(
128	                "SELECT segment_id, language, content, author, source_version, translation_version "
129	                        + "FROM translation WHERE document_id = ? ORDER BY segment_id, language",
130	                TRANSLATION_MAPPER, documentId);
131	    }
132	
133	    /** 插入或覆盖译文（按主键段落+语言唯一）。 */
134	    public void upsertTranslation(long documentId, TranslationRow row) {
135	        int updated = jdbc.update(
136	                "UPDATE translation SET content = ?, author = ?, source_version = ?, translation_version = ?, "
137	                        + "updated_at = CURRENT_TIMESTAMP "
138	                        + "WHERE document_id = ? AND segment_id = ? AND language = ?",
139	                row.content(), row.author(), row.sourceVersion(), row.translationVersion(),
140	                documentId, row.segmentId(), row.language());
141	        if (updated == 0) {
142	            jdbc.update("INSERT INTO translation (document_id, segment_id, language, content, author, "
143	                            + "source_version, translation_version) VALUES (?, ?, ?, ?, ?, ?, ?)",
144	                    documentId, row.segmentId(), row.language(), row.content(), row.author(),
145	                    row.sourceVersion(), row.translationVersion());
146	        }
147	    }
148	
149	    public Optional<ApprovalRow> findApproval(long documentId, String segmentId, String language) {
150	        List<ApprovalRow> rows = jdbc.query(
151	                "SELECT segment_id, language, reviewer, source_version, translation_version "
152	                        + "FROM approval WHERE document_id = ? AND segment_id = ? AND language = ?",
153	                APPROVAL_MAPPER, documentId, segmentId, language);
154	        return rows.stream().findFirst();
155	    }
156	
157	    public List<ApprovalRow> listApprovals(long documentId) {
158	        return jdbc.query(
159	                "SELECT segment_id, language, reviewer, source_version, translation_version "
160	                        + "FROM approval WHERE document_id = ? ORDER BY segment_id, language",
161	                APPROVAL_MAPPER, documentId);
162	    }
163	
164	    /** 插入或覆盖批准（按主键段落+语言唯一）。 */
165	    public void upsertApproval(long documentId, ApprovalRow row) {
166	        int updated = jdbc.update(
167	                "UPDATE approval SET reviewer = ?, source_version = ?, translation_version = ?, "
168	                        + "approved_at = CURRENT_TIMESTAMP "
169	                        + "WHERE document_id = ? AND segment_id = ? AND language = ?",
170	                row.reviewer(), row.sourceVersion(), row.translationVersion(),
171	                documentId, row.segmentId(), row.language());
172	        if (updated == 0) {
173	            jdbc.update("INSERT INTO approval (document_id, segment_id, language, reviewer, "
174	                            + "source_version, translation_version) VALUES (?, ?, ?, ?, ?, ?)",
175	                    documentId, row.segmentId(), row.language(), row.reviewer(),
176	                    row.sourceVersion(), row.translationVersion());
177	        }
178	    }
179	
180	    public void insertSnapshot(long documentId, int publishedVersion, String snapshotJson) {
181	        jdbc.update("INSERT INTO release_snapshot (document_id, published_version, snapshot_json) VALUES (?, ?, ?)",
182	                documentId, publishedVersion, snapshotJson);
183	    }
184	
185	    public Optional<String> findSnapshot(long documentId, int publishedVersion) {
186	        List<String> rows = jdbc.query(
187	                "SELECT snapshot_json FROM release_snapshot WHERE document_id = ? AND published_version = ?",
