3	import org.springframework.http.HttpStatus;
4	import org.springframework.http.ResponseEntity;
5	import org.springframework.http.converter.HttpMessageNotReadableException;
6	import org.springframework.validation.FieldError;
7	import org.springframework.web.bind.MethodArgumentNotValidException;
8	import org.springframework.web.bind.MissingRequestHeaderException;
9	import org.springframework.web.bind.annotation.ExceptionHandler;
10	import org.springframework.web.bind.annotation.RestControllerAdvice;
11	
12	/**
13	 * 全局异常处理：业务异常按状态码返回统一错误体，参数校验失败返回 400。
14	 */
15	@RestControllerAdvice
16	public class GlobalExceptionHandler {
17	
18	    @ExceptionHandler(ApiException.class)
19	    public ResponseEntity<ApiDtos.ErrorResponse> handleApi(ApiException ex) {
20	        return ResponseEntity.status(ex.status())
21	                .body(new ApiDtos.ErrorResponse(ex.code(), ex.getMessage()));
22	    }
23	
24	    @ExceptionHandler(MethodArgumentNotValidException.class)
25	    public ResponseEntity<ApiDtos.ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
26	        String message = ex.getBindingResult().getFieldErrors().stream()
27	                .findFirst()
28	                .map(FieldError::getDefaultMessage)
29	                .orElse("请求参数不合法");
30	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
31	                .body(new ApiDtos.ErrorResponse("BAD_REQUEST", message));
32	    }
33	
34	    @ExceptionHandler(MissingRequestHeaderException.class)
