        ApiResult missing = putJson("/api/documents/" + docId + "/segments/nope/source",
                "{\"requestId\":\"" + newRequestId() + "\",\"sourceText\":\"x\"}");
        assertThat(missing.status()).isEqualTo(404);
    }

